import { INestApplication } from '@nestjs/common';
import { DataSource, Repository } from 'typeorm';
import { Tag } from '../../src/tags/tag.entity';
import { Category } from '../../src/tags/types';
import { resetDatabase, startE2eApp } from './test-app';

// GET /api/tags/:tagId -> TagsController.getTagById -> TagsService.getTagById
const TAGS_PATH = '/api/tags';

// tag_id isn't generated by the database, so tests choose their own. The seed
// migration uses 1-49, so 1000+ stays clear of it even if resets change later.
const TEST_TAG_ID = 1000;
const MISSING_TAG_ID = 999999;

describe('Tag getTagById (E2E)', () => {
  let app: INestApplication;
  let dataSource: DataSource;
  let baseUrl: string;
  let tags: Repository<Tag>;

  beforeAll(async () => {
    ({ app, dataSource, baseUrl } = await startE2eApp());
    tags = dataSource.getRepository(Tag);
  });

  beforeEach(async () => {
    await resetDatabase(dataSource);
  });

  afterAll(async () => {
    await app?.close();
  });

  it('returns the tag stored in the test database', async () => {
    // Arrange: write a row straight into the ephemeral database.
    const seeded = await tags.save(
      tags.create({
        tag_id: TEST_TAG_ID,
        category: Object.values(Category)[0], // any valid category works
        label: 'E2E Test Tag',
        slug: 'e2e-test-tag',
      }),
    );

    // Act: real HTTP request to the running backend.
    const res = await fetch(`${baseUrl}${TAGS_PATH}/${seeded.tag_id}`);

    // Assert: the endpoint returned exactly what is in the database.
    expect(res.status).toBe(200);
    expect(await res.json()).toEqual({
      tag_id: seeded.tag_id,
      category: seeded.category,
      label: seeded.label,
      slug: seeded.slug,
    });
  });

  it('returns 404 when no tag has that id', async () => {
    const res = await fetch(`${baseUrl}${TAGS_PATH}/${MISSING_TAG_ID}`);

    expect(res.status).toBe(404);
  });

  it('returns 400 for a non-numeric id (ParseIntPipe)', async () => {
    const res = await fetch(`${baseUrl}${TAGS_PATH}/not-a-number`);

    expect(res.status).toBe(400);
  });
});
